import React, { createContext, useContext, useRef, useCallback } from 'react';

type SoundType = 'click' | 'success' | 'error' | 'ambient' | 'unlock' | 'pickup';

interface AudioContextType {
  playSound: (type: SoundType) => void;
  stopAmbient: () => void;
  setVolume: (volume: number) => void;
}

const AudioContext = createContext<AudioContextType | null>(null);

const soundFiles = {
  click: '/sounds/click.mp3',
  success: '/sounds/success.mp3',
  error: '/sounds/error.mp3',
  ambient: '/sounds/ambient.mp3',
  unlock: '/sounds/unlock.mp3',
  pickup: '/sounds/pickup.mp3'
};

export const AudioProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const audioRefs = useRef<{ [key in SoundType]?: HTMLAudioElement }>({});
  const volumeRef = useRef<number>(0.5);

  const initAudio = useCallback((type: SoundType) => {
    if (!audioRefs.current[type]) {
      const audio = new Audio(soundFiles[type]);
      audio.volume = volumeRef.current;
      
      if (type === 'ambient') {
        audio.loop = true;
      }
      
      audioRefs.current[type] = audio;
    }
    return audioRefs.current[type]!;
  }, []);

  const playSound = useCallback((type: SoundType) => {
    const audio = initAudio(type);
    
    if (type === 'ambient') {
      audio.play().catch(error => console.error('Erreur de lecture audio:', error));
    } else {
      audio.currentTime = 0;
      audio.play().catch(error => console.error('Erreur de lecture audio:', error));
    }
  }, [initAudio]);

  const stopAmbient = useCallback(() => {
    const ambient = audioRefs.current.ambient;
    if (ambient) {
      ambient.pause();
      ambient.currentTime = 0;
    }
  }, []);

  const setVolume = useCallback((volume: number) => {
    volumeRef.current = volume;
    Object.values(audioRefs.current).forEach(audio => {
      if (audio) {
        audio.volume = volume;
      }
    });
  }, []);

  return (
    <AudioContext.Provider value={{ playSound, stopAmbient, setVolume }}>
      {children}
    </AudioContext.Provider>
  );
};

export const useAudio = () => {
  const context = useContext(AudioContext);
  if (!context) {
    throw new Error('useAudio doit être utilisé à l\'intérieur d\'un AudioProvider');
  }
  return context;
}; 