import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Typography,
  Box,
  IconButton,
  Tooltip
} from '@mui/material';
import { Puzzle } from '../puzzles/types';
import { useGame } from '../context/GameContext';
import { useAudio } from '../context/AudioContext';

interface Props {
  puzzle: Puzzle;
  open: boolean;
  onClose: () => void;
}

const PuzzleDialog: React.FC<Props> = ({ puzzle, open, onClose }) => {
  const [answer, setAnswer] = useState('');
  const [showHint, setShowHint] = useState(false);
  const [error, setError] = useState(false);
  const { dispatch } = useGame();
  const { playSound } = useAudio();

  const handleSubmit = () => {
    if (answer.toLowerCase().trim() === puzzle.solution.toLowerCase()) {
      playSound('success');
      dispatch({ type: 'SOLVE_PUZZLE', puzzleId: puzzle.id });
      
      if (puzzle.reward) {
        dispatch({
          type: 'ADD_ITEM',
          item: {
            id: puzzle.reward.id,
            name: 'Nouvel objet trouvé !',
            description: 'Vous avez obtenu un nouvel objet en résolvant l\'énigme.'
          }
        });
        playSound('pickup');
      }
      
      onClose();
    } else {
      playSound('error');
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  const handleHintToggle = () => {
    playSound('click');
    setShowHint(!showHint);
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose}
      PaperProps={{
        sx: {
          backgroundColor: 'rgba(0, 0, 0, 0.9)',
          color: '#fff',
          minWidth: '400px'
        }
      }}
    >
      <DialogTitle sx={{ borderBottom: '1px solid #333' }}>
        {puzzle.name}
      </DialogTitle>

      <DialogContent sx={{ mt: 2 }}>
        <Typography variant="body1" sx={{ mb: 3 }}>
          {puzzle.description}
        </Typography>

        {showHint && puzzle.hint && (
          <Box sx={{ 
            mb: 3, 
            p: 2, 
            backgroundColor: 'rgba(255, 68, 0, 0.1)',
            border: '1px solid #ff4400',
            borderRadius: 1
          }}>
            <Typography variant="body2" color="primary">
              Indice : {puzzle.hint}
            </Typography>
          </Box>
        )}

        <TextField
          fullWidth
          variant="outlined"
          label="Votre réponse"
          value={answer}
          onChange={(e) => setAnswer(e.target.value)}
          error={error}
          helperText={error ? "Ce n'est pas la bonne réponse" : ""}
          sx={{
            '& .MuiOutlinedInput-root': {
              color: '#fff',
              '& fieldset': {
                borderColor: '#333',
              },
              '&:hover fieldset': {
                borderColor: '#666',
              },
            },
            '& .MuiInputLabel-root': {
              color: '#999',
            },
          }}
        />
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #333', p: 2 }}>
        {puzzle.hint && (
          <Button
            color="secondary"
            onClick={handleHintToggle}
          >
            {showHint ? "Cacher l'indice" : "Voir l'indice"}
          </Button>
        )}
        <Button onClick={() => {
          playSound('click');
          onClose();
        }}>
          Annuler
        </Button>
        <Button 
          variant="contained" 
          color="primary"
          onClick={handleSubmit}
        >
          Valider
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default PuzzleDialog; 