import React, { useState } from 'react';
import {
  Drawer,
  List,
  ListItem,
  ListItemText,
  IconButton,
  Typography,
  Box,
  Tooltip,
  SvgIcon
} from '@mui/material';
import { useGame } from '../context/GameContext';

// Création d'une icône personnalisée
const InventoryIcon = (props: any) => (
  <SvgIcon {...props}>
    <path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm-1 14H5c-.55 0-1-.45-1-1V7c0-.55.45-1 1-1h14c.55 0 1 .45 1 1v10c0 .55-.45 1-1 1z" />
  </SvgIcon>
);

const Inventory: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const { state } = useGame();

  const toggleDrawer = () => {
    setIsOpen(!isOpen);
  };

  return (
    <>
      <Tooltip title="Inventaire" placement="left">
        <IconButton
          onClick={toggleDrawer}
          sx={{
            position: 'fixed',
            right: 20,
            top: 20,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            color: '#fff',
            '&:hover': {
              backgroundColor: 'rgba(0, 0, 0, 0.7)',
            },
          }}
        >
          <InventoryIcon />
        </IconButton>
      </Tooltip>

      <Drawer
        anchor="right"
        open={isOpen}
        onClose={toggleDrawer}
        PaperProps={{
          sx: {
            width: 300,
            backgroundColor: 'rgba(0, 0, 0, 0.9)',
            color: '#fff',
          },
        }}
      >
        <Box sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ mb: 2 }}>
            Inventaire
          </Typography>
          
          <List>
            {state.inventory.length === 0 ? (
              <ListItem>
                <ListItemText 
                  primary="Inventaire vide"
                  sx={{ color: 'grey.500' }}
                />
              </ListItem>
            ) : (
              state.inventory.map((item) => (
                <ListItem key={item.id}>
                  <ListItemText
                    primary={item.name}
                    secondary={item.description}
                    secondaryTypographyProps={{ sx: { color: 'grey.400' } }}
                  />
                </ListItem>
              ))
            )}
          </List>
        </Box>
      </Drawer>
    </>
  );
};

export default Inventory; 