import React from 'react';
import {
  Card,
  CardContent,
  Typography,
  Button,
  Box,
  Tooltip
} from '@mui/material';
import { InteractiveObject as IInteractiveObject } from '../puzzles/types';
import { useGame } from '../context/GameContext';

interface Props {
  object: IInteractiveObject;
}

const InteractiveObject: React.FC<Props> = ({ object }) => {
  const { state } = useGame();
  
  const canInteract = !object.requiredItems || 
    object.requiredItems.every(itemId => 
      state.inventory.some(item => item.id === itemId)
    );

  const handleInteraction = () => {
    if (!canInteract) {
      return;
    }
    object.onInteract();
  };

  if (!object.isVisible) {
    return null;
  }

  return (
    <Card 
      sx={{
        backgroundColor: 'rgba(0, 0, 0, 0.7)',
        border: '1px solid #333',
        transition: 'all 0.3s ease',
        '&:hover': {
          transform: 'scale(1.02)',
          borderColor: '#666'
        }
      }}
    >
      <CardContent>
        <Typography variant="h6" color="primary">
          {object.name}
        </Typography>
        
        <Typography variant="body2" sx={{ color: '#ccc', mb: 2 }}>
          {object.description}
        </Typography>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
          <Tooltip 
            title={!canInteract ? "Il vous manque des objets nécessaires" : ""}
            placement="top"
          >
            <span>
              <Button
                variant="contained"
                color="primary"
                onClick={handleInteraction}
                disabled={!canInteract}
                size="small"
              >
                Examiner
              </Button>
            </span>
          </Tooltip>
        </Box>
      </CardContent>
    </Card>
  );
};

export default InteractiveObject; 