import React from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Button,
  Container,
  Typography,
  Paper,
  Stack
} from '@mui/material';

const MainMenu: React.FC = () => {
  const navigate = useNavigate();

  const startGame = () => {
    navigate('/room/entrance');
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'linear-gradient(to bottom, #1a1a1a, #000000)'
      }}
    >
      <Container maxWidth="sm">
        <Paper
          elevation={24}
          sx={{
            p: 4,
            textAlign: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            border: '1px solid #333'
          }}
        >
          <Typography
            variant="h2"
            component="h1"
            sx={{
              mb: 4,
              color: '#ff4400',
              textShadow: '0 0 10px rgba(255, 68, 0, 0.5)'
            }}
          >
            Escape Game
          </Typography>
          
          <Stack spacing={3}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={startGame}
              sx={{ fontSize: '1.2rem' }}
            >
              Commencer l'aventure
            </Button>
            
            <Button
              variant="outlined"
              color="secondary"
              size="large"
              sx={{ fontSize: '1.2rem' }}
            >
              Comment jouer
            </Button>
          </Stack>
        </Paper>
      </Container>
    </Box>
  );
};

export default MainMenu; 