import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Box, Button, Typography } from '@mui/material';
import { useGame } from '../context/GameContext';
import InteractiveObject from '../components/InteractiveObject';
import PuzzleDialog from '../components/PuzzleDialog';
import { Room, Puzzle as IPuzzle } from '../puzzles/types';

const rooms: { [key: string]: Room } = {
  entrance: {
    id: 'entrance',
    title: "Hall d'entrée",
    description: "Vous vous trouvez dans un hall faiblement éclairé. Les murs sont couverts de symboles étranges et une vieille horloge semble s'être arrêtée à minuit.",
    exits: {
      north: 'library',
      east: 'study'
    },
    objects: [
      {
        id: 'clock',
        name: 'Horloge ancienne',
        description: "Une horloge imposante dont les aiguilles sont bloquées sur minuit. Il y a quelque chose d'étrange dans son mécanisme.",
        type: 'puzzle',
        isVisible: true,
        onInteract: () => {} // Sera défini plus tard
      },
      {
        id: 'symbols',
        name: 'Symboles muraux',
        description: "Des symboles mystérieux sont gravés sur les murs. Ils semblent former une sorte de message.",
        type: 'clue',
        isVisible: true,
        onInteract: () => {} // Sera défini plus tard
      }
    ],
    puzzles: [
      {
        id: 'clock_puzzle',
        name: "L'énigme de l'horloge",
        description: "Les aiguilles de l'horloge semblent pouvoir être tournées. Quelle heure faut-il indiquer ?",
        isSolved: false,
        solution: "3:15",
        hint: "Regardez attentivement les symboles sur les murs...",
        reward: {
          type: 'item',
          id: 'key_library'
        }
      }
    ]
  },
  library: {
    id: 'library',
    title: 'Bibliothèque',
    description: "Des étagères poussiéreuses s'élèvent jusqu'au plafond. Certains livres semblent cacher des secrets.",
    exits: {
      south: 'entrance',
      east: 'laboratory'
    },
    objects: [
      {
        id: 'bookshelf',
        name: 'Étagère mystérieuse',
        description: "Une étagère particulière attire votre attention. Certains livres semblent pouvoir être déplacés.",
        type: 'puzzle',
        isVisible: true,
        onInteract: () => {} // Sera défini plus tard
      }
    ],
    puzzles: [
      {
        id: 'bookshelf_puzzle',
        name: "L'ordre des livres",
        description: "Les livres doivent être placés dans un ordre précis. Un indice sur le côté indique : 'Le rouge vient avant le bleu, mais après le vert.'",
        isSolved: false,
        solution: "vert-rouge-bleu",
        hint: "La couleur est la clé.",
        reward: {
          type: 'item',
          id: 'laboratory_key'
        }
      }
    ],
    isLocked: true,
    requiredItems: ['key_library']
  },
  study: {
    id: 'study',
    title: 'Bureau',
    description: "Un bureau ancien trône au centre de la pièce. Des papiers sont éparpillés partout et un coffre-fort est visible dans un coin.",
    exits: {
      west: 'entrance',
      north: 'laboratory'
    },
    objects: [
      {
        id: 'safe',
        name: 'Coffre-fort',
        description: "Un coffre-fort ancien avec un cadran rotatif. Il semble nécessiter une combinaison à 4 chiffres.",
        type: 'puzzle',
        isVisible: true,
        onInteract: () => {}
      },
      {
        id: 'papers',
        name: 'Documents éparpillés',
        description: "Des papiers couverts de notes et de calculs. Certains nombres sont entourés en rouge.",
        type: 'clue',
        isVisible: true,
        onInteract: () => {}
      }
    ],
    puzzles: [
      {
        id: 'safe_puzzle',
        name: 'Le coffre-fort',
        description: "Le coffre-fort nécessite une combinaison à 4 chiffres. Les documents sur le bureau pourraient contenir des indices.",
        isSolved: false,
        solution: "1842",
        hint: "Additionnez les nombres entourés en rouge et divisez par 2.",
        reward: {
          type: 'item',
          id: 'strange_key'
        }
      }
    ]
  },
  laboratory: {
    id: 'laboratory',
    title: 'Laboratoire',
    description: "Des fioles mystérieuses et des appareils étranges remplissent cette pièce. L'air est chargé d'une odeur particulière.",
    exits: {
      west: 'library',
      south: 'study'
    },
    objects: [
      {
        id: 'chemistry_set',
        name: 'Set de chimie',
        description: "Un ensemble de fioles colorées avec des étiquettes. Certaines semblent pouvoir être mélangées.",
        type: 'puzzle',
        isVisible: true,
        onInteract: () => {}
      },
      {
        id: 'notebook',
        name: 'Carnet de notes',
        description: "Un carnet rempli de formules chimiques et d'annotations.",
        type: 'clue',
        isVisible: true,
        onInteract: () => {}
      }
    ],
    puzzles: [
      {
        id: 'chemistry_puzzle',
        name: 'La formule secrète',
        description: "Créez la bonne combinaison de produits chimiques. Le carnet pourrait contenir des indices sur l'ordre à suivre.",
        isSolved: false,
        solution: "rouge-bleu-vert",
        hint: "La réaction doit créer une lumière arc-en-ciel.",
        reward: {
          type: 'item',
          id: 'final_key'
        }
      }
    ],
    isLocked: true,
    requiredItems: ['laboratory_key']
  }
};

const GameRoom: React.FC = () => {
  const { roomId } = useParams<{ roomId: string }>();
  const navigate = useNavigate();
  const { state, dispatch } = useGame();
  const [selectedPuzzle, setSelectedPuzzle] = useState<IPuzzle | null>(null);
  
  const currentRoom = rooms[roomId || 'entrance'];

  useEffect(() => {
    if (!currentRoom) {
      navigate('/room/entrance');
      return;
    }
    
    if (currentRoom.isLocked && currentRoom.requiredItems) {
      const hasRequiredItems = currentRoom.requiredItems.every(itemId =>
        state.inventory.some(item => item.id === itemId)
      );
      
      if (!hasRequiredItems) {
        navigate('/room/entrance');
        return;
      }
    }
    
    dispatch({ type: 'CHANGE_ROOM', roomId: roomId || 'entrance' });
  }, [roomId, navigate, dispatch, currentRoom, state.inventory]);

  if (!currentRoom) {
    return null;
  }

  const handleObjectInteraction = (puzzleId: string) => {
    const puzzle = currentRoom.puzzles.find(p => p.id === puzzleId);
    if (puzzle && !puzzle.isSolved) {
      setSelectedPuzzle(puzzle);
    }
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        padding: 4,
        backgroundColor: '#000',
        color: '#fff',
        display: 'flex',
        flexDirection: 'column',
        gap: 4
      }}
    >
      <Typography variant="h3" component="h1">
        {currentRoom.title}
      </Typography>

      <Typography variant="body1" sx={{ fontSize: '1.2rem' }}>
        {currentRoom.description}
      </Typography>

      <Box sx={{ 
        display: 'flex', 
        flexWrap: 'wrap', 
        gap: 3,
        mt: 2 
      }}>
        {currentRoom.objects.map(object => (
          <Box
            key={object.id}
            sx={{
              flexGrow: 1,
              flexBasis: {
                xs: '100%',
                sm: 'calc(50% - 24px)',
                md: 'calc(33.33% - 24px)'
              }
            }}
          >
            <InteractiveObject
              object={{
                ...object,
                onInteract: () => handleObjectInteraction(object.id)
              }}
            />
          </Box>
        ))}
      </Box>

      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mt: 4 }}>
        {Object.entries(currentRoom.exits).map(([direction, targetRoom]) => {
          const targetRoomData = rooms[targetRoom];
          const isLocked = targetRoomData.isLocked && targetRoomData.requiredItems?.some(
            itemId => !state.inventory.some(item => item.id === itemId)
          );

          return (
            <Button
              key={direction}
              variant="contained"
              color="primary"
              onClick={() => navigate(`/room/${targetRoom}`)}
              disabled={isLocked}
              sx={{ opacity: isLocked ? 0.5 : 1 }}
            >
              {`Aller vers ${direction}${isLocked ? ' (Verrouillé)' : ''}`}
            </Button>
          );
        })}
      </Box>

      {selectedPuzzle && (
        <PuzzleDialog
          puzzle={selectedPuzzle}
          open={true}
          onClose={() => setSelectedPuzzle(null)}
        />
      )}
    </Box>
  );
};

export default GameRoom; 